import{_ as s,a0 as p,w as l,s as n,ao as u,I as r,a1 as a,A as i,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"如何使用 VLC 媒体播放器旋转视频 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 VLC 媒体播放器旋转视频 | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 VLC 媒体播放器旋转视频 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 VLC 媒体播放器旋转视频 | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230819 How to Rotate a Video With VLC Media Player","title":"如何使用 VLC 媒体播放器旋转视频","tag":"202308","desc":""},"relativePath":"202308/20230819 How to Rotate a Video With VLC Media Player.md","filePath":"[post].md"}'),d={name:"202308/20230819 How to Rotate a Video With VLC Media Player.md"};function m(b,t,f,g,C,c){const o=p("Link");return l(),n("div",null,[t[16]||(t[16]=u('<h1 id="如何使用-vlc-媒体播放器旋转视频" tabindex="-1">如何使用 VLC 媒体播放器旋转视频 <a class="header-anchor" href="#如何使用-vlc-媒体播放器旋转视频" aria-label="Permalink to “如何使用 VLC 媒体播放器旋转视频”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202308/26/110201gf37d3djvis66seu.jpg" alt=""></p><blockquote><p>这个多功能的 VLC 媒体播放器还可以旋转视频方向。在桌面上观看智能手机录制的视频相当方便。</p></blockquote><p>有时，你会遇到以显示方向错误的视频。使用智能手机摄像头拍摄的视频很可能会以这种方式出现。</p><p>如果你可以将其旋转到方便的方向，那么效果会更好。</p><p>功能丰富的 VLC 媒体播放器提供了一种旋转视频的方法。你可以：</p><ul><li>暂时旋转视频（下次播放时需要再次旋转）</li><li>永久旋转视频（视频将始终以新方向播放）</li></ul><p>让我们看看如何实现这两者之一。</p><h3 id="在-vlc-中暂时旋转视频" tabindex="-1">在 VLC 中暂时旋转视频 <a class="header-anchor" href="#在-vlc-中暂时旋转视频" aria-label="Permalink to “在 VLC 中暂时旋转视频”">​</a></h3><p>让我们看看如何在 VLC 中临时旋转视频。也就是说，完成该过程后，它不会反映在实际文件上。这对于查看文件或测试文件很有用。</p><h4 id="使用预设值旋转视频" tabindex="-1">使用预设值旋转视频 <a class="header-anchor" href="#使用预设值旋转视频" aria-label="Permalink to “使用预设值旋转视频”">​</a></h4><p>在此方法中，你可以将视频旋转 90 度、180 度和 270 度。这是你大多数时候所需要的。</p><p>打开 VLC 并选择要旋转的视频。</p><p><img src="https://itsfoss.com/content/images/2023/08/open-a-file-in-vlc.png" alt="Open File in VLC"></p><p>单击主菜单上的 “<ruby>工具<rt>Tools</rt></ruby>”，然后转到 “<ruby>效果和滤镜<rt>Effects and Filters</rt></ruby>”。你也可以按快捷键 <code>CTRL + E</code>。</p><p><img src="https://itsfoss.com/content/images/2023/08/effects-and-filters-in-main-menu.png" alt="Tools &gt; Effects and Filters"></p><p>在 “效果和滤镜” 页面上，选择 “<ruby>视频效果<rt>Video Effects</rt></ruby>” 选项卡，然后进入 “<ruby>几何<rt>Geometry</rt></ruby>”。现在，选中 “<ruby>变换<rt>Transform</rt></ruby>” 复选框。</p><p><img src="https://itsfoss.com/content/images/2023/08/rotate-video-in-transform.png" alt="Set the Rotation"></p><p>这将激活一个下拉菜单。从那里，选择你需要的适当旋转，如 90 度、180 度、水平翻转等。你可以在 VLC 窗口中查看变化。</p><p>对更改感到满意后，按 “<ruby>保存<rt>Save</rt></ruby>” 按钮以所选方向保存配置。</p><h4 id="使用自定义值旋转视频" tabindex="-1">使用自定义值旋转视频 <a class="header-anchor" href="#使用自定义值旋转视频" aria-label="Permalink to “使用自定义值旋转视频”">​</a></h4><p>需要将视频旋转到可用预设以外的方向？ VLC 也有一个选项。</p><p>首先，像上一步一样，打开媒体，然后转到 “工具 &gt; 效果和滤镜 &gt; 视频效果 &gt; 几何”。</p><p>现在，单击 “<ruby>旋转<rt>Rotate</rt></ruby>” 复选框，你可以看到交互式圆形滑块现已激活。</p><blockquote><p>🚧 对于不规则的旋转值（例如 230 度等），某些部分都会从视频中删除。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/08/rotate.png" alt="Irregular rotation"></p><p>移动滑块以获得正确的旋转。你可以在 VLC 窗口中看到视频出现的变化。确定更改后，请按 “保存” 按钮保存该配置。</p><blockquote><p>🚧 请记住，此配置在此阶段不会永久应用于视频。但是，如果你按 “保存”，方向也会暂时应用于 VLC 中播放的其他视频。</p></blockquote><h3 id="永久旋转视频" tabindex="-1">永久旋转视频 <a class="header-anchor" href="#永久旋转视频" aria-label="Permalink to “永久旋转视频”">​</a></h3><p>你知道了如何临时旋转文件。永久保存视频文件更改也需要该步骤。</p><h4 id="第-1-步-转换视频" tabindex="-1">第 1 步：转换视频 <a class="header-anchor" href="#第-1-步-转换视频" aria-label="Permalink to “第 1 步：转换视频”">​</a></h4><p>这是前一部分。打开视频文件，然后进行所需的旋转。确认特定视频所需的旋转后，按照上一步中的说明保存该配置。</p><h4 id="第-2-步-保存视频" tabindex="-1">第 2 步：保存视频 <a class="header-anchor" href="#第-2-步-保存视频" aria-label="Permalink to “第 2 步：保存视频”">​</a></h4><p>现在，打开 VLC 并单击 “<ruby>媒体<rt>Media</rt></ruby> &gt; <ruby>转换/保存<rt>Convert/Save</rt></ruby>”。这可以在没有打开任何视频文件的情况下进行，因为无论如何我们都不会处理当前打开的视频。</p><p><img src="https://itsfoss.com/content/images/2023/08/click-on-convert-and-save.png" alt="Click on Convert/Save"></p><p>在下一个对话框中，使用 “<ruby>添加<rt>Add</rt></ruby>” 按钮选择要旋转的文件（在上一步中测试以确认所需旋转的文件）。然后按 “<ruby>转换并保存<rt>Convert and Save</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/08/Add-files-to-convert.png" alt="Add Files to convert"></p><p>接下来，选择所需的视频输出，然后单击相邻的设置按钮，如下所示。</p><p><img src="https://itsfoss.com/content/images/2023/08/click-on-config-button.png" alt="Click on Configuration button"></p><p>出现了配置文件设置窗口。在其上，进入 “<ruby>视频编解码器<rt>Video Codec</rt></ruby>”，然后转到 “<ruby>过滤器<rt>Filters</rt></ruby>” 选项卡。在这里，你必须根据需要应用过滤器。一个是 “<ruby>旋转视频过滤器<rt>Rotate Video Filter</rt></ruby>”，另一个是 “<ruby>视频转换过滤器<rt>Video transformation Filter</rt></ruby>”。</p><p>如果你已使用 “变换” 按钮对视频应用固定变换，请选择 “<ruby>视频变换过滤器<rt>Video transformation Filter</rt></ruby>”。另一方面，如果你对视频进行了一些不规则的旋转，请选择 “旋转视频过滤器”。</p><p><img src="https://itsfoss.com/content/images/2023/08/apply-filters.png" alt="Apply the Filters"></p><p>检查后，按 “保存”按钮。</p><p>现在，选择输出文件位置，我们要在其中保存转换后的文件。</p><p><img src="https://itsfoss.com/content/images/2023/08/give-an-output-file-name.png" alt="Select Output file location"></p><p>应给出一个新的文件名，这可以通过进入你选择的目录并只需在顶部栏上输入你选择的名称来完成。</p><blockquote><p>💡 建议提供一个新的唯一名称，以避免文件覆盖和数据丢失。</p></blockquote><p><img src="https://itsfoss.com/content/images/2023/08/select-filename.png" alt="Give file name"></p><p>按 “<ruby>开始<rt>Start</rt></ruby>” 开始转换。</p><p>转换将需要一些时间，具体取决于你的视频。完成后，你将获得旋转的视频，可以在任何视频播放器上查看。</p><blockquote><p>🚧 转换视频后（无论是永久的还是临时的），最好在 “工具 &gt; 效果和滤镜 &gt; 视频效果 &gt; 几何” 中关闭应用的旋转。否则，以后使用 VLC 播放的视频将出现旋转。</p></blockquote><p>我希望你喜欢这个 VLC 技巧。欢迎你提出建议和反馈。</p><p>同时，你还可以学习这个很酷的 VLC 自动下载字幕的技巧。</p>',53)),r("blockquote",null,[r("p",null,[r("strong",null,[a(o,{href:"https://itsfoss.com/download-subtitles-automatically-vlc-media-player-ubuntu/"},{default:i(()=>[...t[0]||(t[0]=[e("在 VLC 中自动下载字幕",-1)])]),_:1})])])]),t[17]||(t[17]=r("p",null,[r("em",null,"（题图：MJ/b604f181-660a-4f05-bdd2-49b5b6da0bae）")],-1)),t[18]||(t[18]=r("hr",null,null,-1)),r("p",null,[t[2]||(t[2]=e("via: ",-1)),a(o,{href:"https://itsfoss.com/rotate-video-vlc/"},{default:i(()=>[...t[1]||(t[1]=[e("https://itsfoss.com/rotate-video-vlc/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=e("作者：",-1)),a(o,{href:"https://itsfoss.com/author/sreenath/"},{default:i(()=>[...t[3]||(t[3]=[e("Sreenath",-1)])]),_:1}),t[8]||(t[8]=e(" 选题：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[4]||(t[4]=[e("lujun9972",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),a(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创编译，",-1)),a(o,{href:"https://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const L=s(d,[["render",m]]);export{V as __pageData,L as default};
